/// <summary>
/// MPJ_31513 Invoicing Design
/// Extension methods for CustInvoiceTrans table
/// </summary>
[ExtensionOf(TableStr(CustInvoiceTrans))]
final class METCustInvoiceTransTable_Extension
{

}

Method.Source:
    /// <summary>
    ///  Insert method for CustInvoiceTrans
    /// </summary>
    public void insert()
    {
        //CB272 for updating the METCase and METGrossWeight fields as on the init level qty is blank.
        SalesLine salesLine = SalesLine::find(this.SalesId, this.LineNum);
        container salesLineActuals;

        if(salesLine)
        {
            this.updateMETLitres(salesLine);
            
            salesLineActuals = salesLine.computeSalesLineActualsForQuantity(this.Qty);

            if (salesLineActuals)
            {
                this.METCase         = any2Int(conPeek(salesLineActuals, 1));
                this.METGrossWeight  = any2Real(conPeek(salesLineActuals, 2));
                this.METActualWeight = any2Real(conPeek(salesLineActuals, 3));
                this.METPickedCases  = any2Int(conPeek(salesLineActuals, 4));
                this.METPickedBrokenCases = any2Int(conPeek(salesLineActuals, 5));
            }
        }

        //Bug 385687 - [T]METSalesInvoiceLineV3Entity_Extension.postLoad() performance issue - Start.
        this.METGTIN = this.metGetSalesInvoiceLineGTIN();
        //Bug 385687 - [T]METSalesInvoiceLineV3Entity_Extension.postLoad() performance issue - End.

        next insert();
    }

    /// <summary>
    /// Extension of init from Sales line
    /// </summary>
    /// <param name = "salesLine">Sales line</param>
    /// <param name = "_salesParmLine">Sales parm line</param>
    void initFromSalesLine(SalesLine salesLine, SalesParmLine _salesParmLine)
    {
        next initFromSalesLine(salesLine, _salesParmLine);

        this.METItemType = salesLine.displayMETItemType();
        this.METFreeItemExciseVendClaimStatus = salesLine.LineAmount==0? METFreeItemExciseVendClaimStatus::Pending : METFreeItemExciseVendClaimStatus::NotRequired;
        
        //Bug 385687 - [T]METSalesInvoiceLineV3Entity_Extension.postLoad() performance issue - Start.
        this.METSalesInvIndicator = this.metGetInvoiceLineIndicators(salesLine);
        //Bug 385687 - [T]METSalesInvoiceLineV3Entity_Extension.postLoad() performance issue - End.
    }

/// <summary>
/// CB272 update metLitres field based on SalesLine unit of measure and quantity.
/// </summary>
private void updateMETLitres(SalesLine _salesline)
{
    //if salesLine unit is litres.
    if (_salesline.SalesUnit == METConstants::litresLT)
    {
        this.METLitres = any2Str(this.Qty);
    }
    else
    {
        // Case: if sales unit is each
        if (_salesline.SalesUnit == METConstants::unitEach)
        {
            this.METLitres = any2Str(this.Qty * METInventTable::find(_salesline.itemid).BottleSize);
        }
        else
        {
            EcoResProduct product = EcoResProduct::findByProductNumber(_salesline.itemid);
            Recid fromUOM = UnitOfMeasure::unitOfMeasureIdBySymbol(_salesline.SalesUnit);
            Recid eaUOM = UnitOfMeasure::unitOfMeasureIdBySymbol(METConstants::unitEach);
            // if sales unit is not each - convert to each.
            // Case: X → ea
            if (UnitOfMeasureConversion::findByConversion(fromUOM, eaUOM, product.RecId).RecId)
            {
                Qty qtyInEa = UnitOfMeasureConverter::convert(this.Qty, fromUOM, eaUOM, NoYes::No, product.RecId, NoYes::No);
                this.METLitres = any2Str(qtyInEa * METInventTable::find(_salesline.itemid).BottleSize);
            }
        }
    }
}

/// <summary>
/// Get Metcash item type for item on the SalesLine.
/// </summary>
/// <returns>Metcash item type</returns>
[SysClientCacheDataMethodAttribute(true)]
public display METItemTypes displayMETItemType()
{
    return InventTable::metGetItemType(this.ItemId, this.inventDim().InventSiteId);
}

    static boolean existByInvoiceIdAndItemId(CustInvoiceId _custInvoiceId, ItemId _itemId)
    {
        if (!_custInvoiceId || !_itemId)
        {
            return false;
        }

        CustInvoiceTrans custInvoiceTrans;

        return (select firstonly RecId from custInvoiceTrans
                    where custInvoiceTrans.InvoiceId == _custInvoiceId
                       && custInvoiceTrans.ItemId == _itemId).RecId != 0;
    }

    /// <summary>
    /// Override of the standard contributionMargin display method.
    /// For return invoice lines (SalesType == ReturnItem with an original invoice reference):
    ///   Returns the summed Value from METSalesLinePriceComponent where PriceComponent == Margins.
    ///   Returns 0 if no Margins component is defined for the line.
    /// For all other invoice lines: delegates to the standard cost-based calculation.
    /// </summary>
    [SysClientCacheDataMethodAttribute(true)]
    public display SalesContributionMargin contributionMargin()
    {
        SalesContributionMargin standardMargin = next contributionMargin();

        SalesTable      salesTable    = SalesTable::find(this.SalesId);
        METSalesTable   metSalesTable = salesTable.metSalesTable();

        // Only apply Margins price component logic for return invoice lines
        boolean isReturnLine = salesTable.SalesType == SalesType::ReturnItem
                            && metSalesTable.OriginalInvoice;

        if (!isReturnLine || !this.InventTransId)
        {
            return standardMargin;
        }

        // Return invoice line: sum the Margins price component value for this InventTransId.
        METSalesLinePriceComponent  metSalesLinePriceComponent;
        METComponentCode            metComponentCode;

        select sum(Value) from metSalesLinePriceComponent
            where metSalesLinePriceComponent.InventTransId == this.InventTransId
            exists join metComponentCode
                where metComponentCode.Component      == metSalesLinePriceComponent.Component
                   && metComponentCode.PriceComponent == METPriceComponent::Margins;

        return metSalesLinePriceComponent.Value;
    }

    /// <summary>
    /// Bug 385687 - [T]METSalesInvoiceLineV3Entity_Extension.postLoad() performance issue.
    /// Fetches invoice line indicatos.
    /// </summary>
    /// <param name = "_salesLine">SalesLine.</param>
    /// <returns>Invoice line indicators.</returns>
    private str metGetInvoiceLineIndicators(SalesLine _salesLine)
    {
        #define.Separator(',')

        METSalesInvoiceIndicatorView  metSalesInvoiceIndicatorView;
        METSalesLine                  metSalesLine;
        Set                           invIndicatorsSet;
        List                          parts;
        str                           ret;

        metSalesLine     = _salesLine.metSalesLine();
        invIndicatorsSet = new Set(Types::String);
        parts            = new List(Types::String);

        while select CimponentInvoiceIndicator from metSalesInvoiceIndicatorView
            group by metSalesInvoiceIndicatorView.CimponentInvoiceIndicator
                where    metSalesInvoiceIndicatorView.InventTransId              == _salesLine.InventTransId
                     &&  metSalesInvoiceIndicatorView.CimponentInvoiceIndicator  != 0
        {
            str indicatorStr = enum2Str(metSalesInvoiceIndicatorView.CimponentInvoiceIndicator);
            
            parts.addEnd(indicatorStr);
            invIndicatorsSet.add(indicatorStr);
        }

        if (metSalesLine.Indicators && !invIndicatorsSet.in(metSalesLine.Indicators))
        {
            parts.addEnd(metSalesLine.Indicators);
        }

        ret = (parts.elements() > 0) ? con2Str(list2Con(parts), #Separator) : '';

        return ret;;
    }

    /// <summary>
    /// Bug 385687 - [T]METSalesInvoiceLineV3Entity_Extension.postLoad() performance issue.
    /// Gets the GTIN for the sales invoice line based on the item barcode setup for the item and sales unit.
    /// </summary>
    /// <returns>GTIN.</returns>
    private METGTIN metGetSalesInvoiceLineGTIN()
    {
        InventItemBarcode    inventItemBarcode;

        select firstonly ItemBarCode from inventItemBarcode
            where  inventItemBarcode.ItemId  == this.ItemId
                && inventItemBarcode.UnitId  == this.SalesUnit;

        return inventItemBarcode.ItemBarCode;
    }

    /// <summary>
    /// Since we are moving with standard Ax Invoice posting, we need to update the LoadId and ShipmentId on the invoice journal table Earlier it was updating from Finalization process 
    /// </summary>
    public void metUpdateLoadIdAndShipmentId()
    {
        InventTrans                     inventTrans;
        InventTransOrigin               inventTransOrigin;
        WMSOrderTrans                   wmsOrderTrans;
        METSalesOrderShipmentLoadLines  shipmentLoadLines;
        METSalesOrderShipmentLoadHeader shipmentLoadHeader;
        CustInvoiceJour                 custInvoiceJour;

        update_recordset custInvoiceJour
            setting METLoadId     = shipmentLoadHeader.LoadId,
                    METShipmentId = shipmentLoadHeader.ShipmentId
                where custInvoiceJour.InvoiceId           == this.InvoiceId
                       && custInvoiceJour.InvoiceDate         == this.InvoiceDate
                       && custInvoiceJour.NumberSequenceGroup == this.numberSequenceGroup
                       && custInvoiceJour.SalesId             == this.SalesId
                       && custInvoiceJour.METLoadId           == ''
                       && custInvoiceJour.METShipmentId       == ''
            join shipmentLoadHeader
            exists join shipmentLoadLines
                where shipmentLoadLines.ShipmentId == shipmentLoadHeader.ShipmentId
            exists join wmsOrderTrans
                where wmsOrderTrans.RecId == shipmentLoadLines.WMSOrderTransRecId 
                    && wmsOrderTrans.InventTransId == this.InventTransId
            exists join inventTransOrigin
                where inventTransOrigin.InventTransId == wmsOrderTrans.InventTransId
            exists join inventTrans
                where inventTrans.InventTransOrigin == inventTransOrigin.RecId
                   && inventTrans.InvoiceId          == this.InvoiceId
                   && inventTrans.PickingRouteId     == wmsOrderTrans.RouteId;
    }
